const CERT53=window.__GMFQ_DATA.CERT53;
function tvPairOrientation(pair,dir){
const [a,b]=pair.split('/');
// TradingView convention for G8 pairs used in this dashboard.
const canonical = new Set(['EURUSD','GBPUSD','AUDUSD','NZDUSD','USDJPY','USDCHF','USDCAD',
'EURGBP','EURJPY','EURCHF','EURCAD','EURAUD','EURNZD',
'GBPJPY','GBPCHF','GBPCAD','GBPAUD','GBPNZD',
'CHFJPY','CADJPY','AUDJPY','NZDJPY',
'CADCHF','AUDCHF','NZDCHF','AUDCAD','NZDCAD','AUDNZD']);
const direct=a+b, inverse=b+a;
let ticker=canonical.has(direct)?direct:(canonical.has(inverse)?inverse:direct);
const favored = dir==='A'?a:dir==='B'?b:null;
if(!favored) return {ticker,side:'neutral',favored:null};
const base=ticker.slice(0,3), quote=ticker.slice(3,6);
const side=favored===base?'long':favored===quote?'short':'neutral';
return {ticker,side,favored};
}
function overviewPairCard(pair){
const frame=derivePairDecisionFrame(pair);
if(!frame) return '';
const driver=derivePairDriverStructure(pair);
const [a,b]=pair.split('/');
const fav=frame.fav && frame.fav!=='—' ? frame.fav : null;
const dir=fav===a?'A':fav===b?'B':null;
const o=tvPairOrientation(pair,dir);
const cls=o.side==='long'?'longTicker':o.side==='short'?'shortTicker':'';
const state=frame.quality;
const stateCls=frame.quality==='CONTRASTO STRUTTURALE FORTE'?'partial':
frame.quality==='VANTAGGIO RELATIVO PARZIALE'?'partial':'div';
const winner=fav||'Nessuno';
const price=frame.priceReading==='MERCATO GIÀ ALLINEATO'?'il prezzo conferma':
frame.priceReading==='DIVERGENZA DA MONITORARE'?'il prezzo diverge':'il prezzo non è ancora chiaro';
const monitor=frame.missing||'Serve maggiore differenziazione strutturale.';
return `<div class="ideaCard" onclick="showView('pairs');setTimeout(()=>{openPairDetail('${pair}');setTimeout(()=>{appendPairDriverOverlayToDetail('${pair}');appendPairRelativeDynamicsToDetail('${pair}');appendPairTransitionToDetail('${pair}');appendPairRiskOverlayToDetail('${pair}')},0)},0)" style="cursor:pointer"><div class="ideaHead"><span class="ideaPair ${cls}">${o.ticker}</span><span class="ideaLabel ${stateCls}">${state}</span></div><div class="ideaWhy"><b>${winner}</b>${fav?' favorito':' senza vantaggio pulito'} nella struttura canonica Macro + Tassi/CB. ${driver.driver!=='Non determinato'?`Driver: ${driver.driver}. `:''}${price}.</div><div class="ideaChecks"><div class="ideaCheck"><b>Conferma</b>${frame.priceReading==='MERCATO GIÀ ALLINEATO'?'Prezzo già allineato alla struttura':'Serve conferma senza cambiare il core'}</div><div class="ideaCheck"><b>Da monitorare</b>${monitor}</div></div>
